from pytorch_metric_learning import losses,miners
torch.manual_seed(z.SEED);random.seed(z.SEED);torch.set_num_threads(4);rows,pos,valid,_=z.build_split();t=z.teacher_cache(rows);plan=z.epoch_plan(1,pos,valid);m=BR1();o=torch.optim.AdamW(m.parameters(),lr=3e-4,weight_decay=1e-4);s=torch.optim.lr_scheduler.CosineAnnealingLR(o,T_max=4,eta_min=3e-5);e=plan[0];ids=e['row_indices'];lab=torch.tensor(e['labels']);x=torch.stack([z.student_tensor(rows[i],192,352) for i in ids]);y=m(x);tt=torch.from_numpy(t[ids]);task=losses.MultiSimilarityLoss(alpha=1.,beta=50.,base=0.)(y,lab,miners.MultiSimilarityMiner(epsilon=.1)(y,lab));kd=torch.nn.functional.mse_loss(y@y.T,tt@tt.T);tot=task+2*kd;o.zero_grad();tot.backward();ps=[p for p in m.parameters() if p.grad is not None];g=sum(p.grad.abs().sum().item() for p in ps);finite=all(torch.isfinite(p.grad).all() for p in ps);before=[p.detach().clone() for p in m.parameters()];o.step();diff=max(float((p-b).abs().max()) for p,b in zip(m.parameters(),before));A=R/'artifacts/edge_vpr_students/s512_br1_training';save(A/'smoke_v2.pt',model=m,optimizer=o,scheduler=s,current_epoch=1,next_batch_index=1,global_step=1,training_config={'student':'BR1','input':[3,352,192]},epoch_plan=plan,best_metric_name='combined_R@5',best_metric_value=float('-inf'),best_checkpoint_path=None);c=torch.load(A/'smoke_v2.pt',weights_only=False);r={'smoke':'PASS','input':list(x.shape),'student':list(y.shape),'teacher':list(tt.shape),'task':float(task),'kd':float(kd),'total':float(tot),'grad_finite':finite,'grad_parameter_count':len(ps),'grad_sum':g,'max_parameter_update':diff,'optimizer_step':max(int(v['step']) for v in o.state.values()),'checkpoint_keys':sorted(c.keys()),'cursor':[c['current_epoch'],c['next_batch_index'],c['global_step']]};(R/'reports/edge_vpr_students/s512_br1_smoke.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r))
